lines = ["# deps", "pandas==2.2.1", "", "requests==2.31.0", "pytest", "rich", "numpy==1.26.4"]
installed = {"pandas": "2.2.1", "requests": "2.30.0", "pytest": "8.0.0"}
for line in lines:
    line = line.strip()
    if not line or line.startswith("#"):
        continue
    name, _, pinned = line.partition("==")
    if name not in installed:
        print(f"{name}: missing")
    elif pinned and installed[name] != pinned:
        print(f"{name}: mismatch (installed {installed[name]}, pinned {pinned})")
    else:
        print(f"{name}: ok")
